from pathlib import Path
p=Path(__file__).with_name('aplicar_ampliacion_gas.py')
s=p.read_text(encoding='utf-8')
s=s.replace("if len(regs)!=75: raise SystemExit(f'Esperados 75, obtenidos {len(regs)}')","K=len(regs); NV=15; NC=K-NV")
s=s.replace("if totals!=(1679,3142,1245,416): raise SystemExit('Totales: '+str(totals))","esperados=(1604+K,3067+K,1230+NV,356+NC)\n if totals!=esperados: raise SystemExit('Totales: '+str(totals)+' esperados '+str(esperados))")
